import random

def solve_optimal(nums, k):
    arr = sorted(nums)
    left = 0
    total = 0
    for right in range(len(arr)):
        while arr[right] - arr[left] > k:
            left += 1
        total += right - left
    return total

def solve_brute(nums, k):
    total = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if abs(nums[i] - nums[j]) <= k:
                total += 1
    return total

def gen(rng, size):
    low, high = {"tiny": (2, 4), "small": (2, 12), "large": (40, 120)}[size]
    n = rng.randint(low, high)
    return [[rng.randint(-20, 20) for _ in range(n)], rng.randint(0, 10)]

def validate(args):
    nums, k = args
    return 2 <= len(nums) <= 1000 and k >= 0 and all(-10**4 <= x <= 10**4 for x in nums)
